import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"在本地完成第一次检索","description":"","frontmatter":{},"headers":[],"relativePath":"zh/get-started/local.md","filePath":"zh/get-started/local.md","lastUpdated":1793111003000}'),n={name:"zh/get-started/local.md"};function r(l,s,p,o,h,d){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="在本地完成第一次检索" tabindex="-1">在本地完成第一次检索 <a class="header-anchor" href="#在本地完成第一次检索" aria-label="Permalink to &quot;在本地完成第一次检索&quot;">​</a></h1><p>在自己的设备上安装 PaperSeek，连接模型，把一个研究问题变成阅读清单。</p><p>不想安装？改为<a href="./online">在线完成第一次检索</a>。</p><h2 id="_1-安装" tabindex="-1">1. 安装 <a class="header-anchor" href="#_1-安装" aria-label="Permalink to &quot;1. 安装&quot;">​</a></h2><p>需要 <strong>Python 3.12 或更新版本</strong>，并使用独立环境。</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-Het_9" id="tab-Y6PHy-0" checked><label data-title="macOS / Linux" for="tab-Y6PHy-0">macOS / Linux</label><input type="radio" name="group-Het_9" id="tab-93gWju6"><label data-title="Windows PowerShell" for="tab-93gWju6">Windows PowerShell</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;paperseek==1.0.0b5&quot;</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">py </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-3.12</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m venv .venv</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\.venv\\Scripts\\Activate.ps1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pip install </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;paperseek==1.0.0b5&quot;</span></span></code></pre></div></div></div><p>从 1.0.0-beta5 源码检出安装时，改为 <code>python -m pip install ./backend</code>。修改前端源码后，请按<a href="./../developers/contributing">贡献指南</a>中的构建说明操作。</p><h2 id="_2-启动" tabindex="-1">2. 启动 <a class="header-anchor" href="#_2-启动" aria-label="Permalink to &quot;2. 启动&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>打开 <strong><a href="http://127.0.0.1:8765" target="_blank" rel="noreferrer">http://127.0.0.1:8765</a></strong>，使用期间保持终端运行。</p><p>安装包已包含网页界面，运行它不需要 Node.js。</p><h2 id="_3-连接模型" tabindex="-1">3. 连接模型 <a class="header-anchor" href="#_3-连接模型" aria-label="Permalink to &quot;3. 连接模型&quot;">​</a></h2><p>打开侧栏底部的<strong>设置 → 模型 API</strong>，点击<strong>添加连接</strong>。选择 <strong>LLM</strong>、服务商和模型，填写密钥；自定义服务还需要确认基础地址与协议。可先点击<strong>测试连接</strong>检查模型草稿，再点击<strong>保存</strong>。在<strong>默认使用</strong>的<strong>检索与评分</strong>中选择已保存的连接，然后通过侧栏的<strong>文献检索</strong>返回。</p><p>OpenAI Chat Completions、OpenAI Responses 和 Anthropic Messages 是不同协议，只看模型名称无法判断该用哪一种。</p><p>模型草稿的测试不会保存连接。数据源测试有不同的保存行为，见下文。如需提供服务端默认配置，见<a href="./../reference/configuration">配置参考</a>。</p><h2 id="_4-输入问题" tabindex="-1">4. 输入问题 <a class="header-anchor" href="#_4-输入问题" aria-label="Permalink to &quot;4. 输入问题&quot;">​</a></h2><blockquote><p>开源软件如何获得支持长期维护的资金？</p></blockquote><p>如有 OpenAlex 密钥，打开<strong>设置 → 数据源 → OpenAlex → 配置</strong>，填写后点击<strong>保存</strong>。此数据源弹窗中的<strong>测试连接</strong>也会先保存当前密钥和选项，再执行测试；测试失败或随后取消弹窗，都不会撤销这次保存。</p><p>通过侧栏返回<strong>文献检索</strong>，选择 <strong>OpenAlex</strong>。只有必要时才在<strong>更多选项</strong>中限制研究领域。第一次运行可保留 <strong>Auto</strong>，也可以按问题的范围选择检索预算。</p><p>点击<strong>开始检索</strong>，或按 <strong>Ctrl+Enter / ⌘+Enter</strong>，在 PaperSeek 检索和排序时关注各阶段进展。</p><h2 id="_5-阅读结果" tabindex="-1">5. 阅读结果 <a class="header-anchor" href="#_5-阅读结果" aria-label="Permalink to &quot;5. 阅读结果&quot;">​</a></h2><p>打开<strong>检索结果</strong>，查看摘要与相关性理由，导出 CSV、JSON、BibTeX 或 RIS。社区版将历史保存在本地。</p><p>通过侧栏的<strong>检索历史</strong>重新打开某次运行，或点击标题旁的<strong>全部</strong>进入完整列表。有引用数据时查看<strong>引用证据</strong>，也可以勾选文献开始一篇<a href="./../guide/reviews">实验性综述</a>。从侧栏打开<a href="./../guide/bibliometrics">文献计量</a>，可分析完整召回的候选集。</p><h2 id="遇到问题时" tabindex="-1">遇到问题时 <a class="header-anchor" href="#遇到问题时" aria-label="Permalink to &quot;遇到问题时&quot;">​</a></h2><p>先查看<a href="./../reference/troubleshooting">常见问题</a>。本地环境检查可执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>配置有效不代表上游在整个长时间检索中始终有余额或保持可用。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li><a href="./../self-hosting/">自部署</a>：Docker 部署、数据目录、网络访问和备份。</li><li><a href="./../guide/search">检索文献</a>：预算、领域筛选、停止与重连。</li></ul>`,29)])])}const c=a(n,[["render",r]]);export{k as __pageData,c as default};
